scriptCalls.value:
if (!token) return;
if(state) {
  fromUuid("Compendium.pf1.macros.Macro.Pa1s9GAbnGhj4z2A")
    .then(lm => lm.execute({ token, range: 40 }));
} else {
  // Lights off as it comes from Foundry default
  const light = new foundry.data.LightData().toObject();
  token.document.update({ light });
}

if(state) {
  const otherBuffTags = [
    "blessingOfFervorAtkAcRef",
    "blessingOfFervorExtraAtk",
    "blessingOfFervorSpeed",
    "blessingOfFervorSpell",
    "blessingOfFervorStandUp"
  ];

  const otherBuffs = actor.itemTypes.buff.filter(b => otherBuffTags.includes(b.system.tag) && b.system.tag !== item.system.tag);
  otherBuffs.forEach(async (buff) => { await buff.setActive(false) });
}

if(state) {
  const otherBuffTags = [
    "threefoldAspectYoungAdult",
    "threefoldAspectAdult",
    "threefoldAspectElderly"
  ];

  const otherBuffs = actor.itemTypes.buff.filter(b => otherBuffTags.includes(b.system.tag) && b.system.tag !== item.system.tag);
  otherBuffs.forEach(async (buff) => { await buff.setActive(false) });
}

if(state) {
  const cancelTag= "goodHope"

  const otherBuff = actor.itemTypes.buff.find(b => (b.system.tag === cancelTag) && b.system.active);

  if(otherBuff) {
    await otherBuff.setActive(false)
    await item.setActive(false)
  }
}

if(item.system.active)
  await item.setActive(false);
else
  shared.hideChat = true;

if(state) {
  const otherBuffTags = [
    "blessingOfFervorAtkAcRef",
    "blessingOfFervorExtraAtk",
    "blessingOfFervorSpeed",
    "blessingOfFervorSpell",
    "blessingOfFervorStandUp"
  ];

  const otherBuffs = actor.itemTypes.buff.filter(b => otherBuffTags.includes(b.system.tag) && b.system.tag !== item.system.tag);
  otherBuffs.forEach(async (buff) => { await buff.setActive(false) });
}

if(state) {
  const llSettings = actor.system.traits.senses.ll;

  if(llSettings.enabled) {
    await item.setItemDictionaryFlag("lowlight_settings", `${llSettings.multiplier.dim}_${llSettings.multiplier.bright}`);
    await actor.update({'system.traits.senses.ll.multiplier': { dim: llSettings.multiplier.dim * 2, bright: llSettings.multiplier.bright * 2} });
  } else
    await actor.update({'system.traits.senses.ll.enabled': true });
} else {
  const settingsString = await item.getItemDictionaryFlag("lowlight_settings");
  if(settingsString) {
    const [dimMult, brightMult] = settingsString.split("_");
    await actor.update({'system.traits.senses.ll.multiplier': { dim: dimMult, bright: brightMult } });
    await item.removeItemDictionaryFlag("lowlight_settings");
  } else
    await actor.update({'system.traits.senses.ll.enabled': false });
}

if(item.system.active)
  await item.setActive(false);
else
  shared.hideChat = true;

if(state) {
  const otherBuffTags = [
    "threefoldAspectYoungAdult",
    "threefoldAspectAdult",
    "threefoldAspectElderly"
  ];

  const otherBuffs = actor.itemTypes.buff.filter(b => otherBuffTags.includes(b.system.tag) && b.system.tag !== item.system.tag);
  otherBuffs.forEach(async (buff) => { await buff.setActive(false) });
}

if(item.system.active)
  await item.setActive(false);
else
  shared.hideChat = true;
